(() => {
  const STORAGE_KEY='intercvl-zese-charte-ia-v1';
  const LAB_KEY='intercvl-zese-atelier-ia-v1';
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const uid=()=>`id_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;

  const poleData={
    1:{icon:'🔵',title:'IA et travail scolaire',central:'Comment utiliser l’IA sans tricher ?',color:'#3267d6',questions:[
      "Quand l’IA cesse-t-elle d’être une aide pour devenir un remplacement de votre réflexion ?",
      "Si l’IA vous aide beaucoup à rédiger, qui est réellement l’auteur du travail ?",
      "Comment éviter que l’accès inégal aux outils IA crée de nouvelles inégalités entre élèves ?",
      "Si l’IA peut expliquer, résumer et générer, qu’est-ce qu’un élève doit encore savoir faire lui-même ?"
    ],dilemmas:[
      {text:"Lina demande à une IA de lui proposer trois plans de dissertation. Elle en choisit un puis rédige tout elle-même.",question:"Est-ce un usage acceptable ? À quelles conditions ?"},
      {text:"Noah demande à une IA de rédiger son devoir entier, puis change quelques mots avant de le rendre.",question:"Où placez-vous la limite entre aide et triche ?"},
      {text:"Deux élèves rendent un devoir de même qualité. L’un avait accès à un outil IA payant très performant, l’autre non.",question:"Est-ce équitable ? Que devrait prévoir l’établissement ?"}
    ]},
    2:{icon:'🟢',title:'IA et information',central:'Comment éviter la manipulation ?',color:'#208c5a',questions:[
      "Si une IA peut imiter une autorité ou une émotion humaine, comment savoir à qui faire confiance ?",
      "Quelle est votre responsabilité quand vous partagez une information qui pourrait avoir été générée par IA ?",
      "Comment réagir face à une image ou une vidéo spectaculaire dont la source est inconnue ?",
      "Quand une IA donne une réponse fausse avec beaucoup d’assurance, qui doit vérifier et comment ?"
    ],dilemmas:[
      {text:"Une vidéo montrant une personnalité politique circule dans votre groupe. Elle paraît réelle, mais personne ne connaît la source.",question:"Que faites-vous avant de la partager ?"},
      {text:"Une IA vous donne une information qui confirme exactement ce que vous pensiez déjà, mais vous ne trouvez aucune source fiable.",question:"La croyez-vous ? Pourquoi ?"},
      {text:"Un compte publie uniquement des faits réels, mais les présente de manière très émotionnelle pour vous pousser à réagir.",question:"Information ou manipulation ? Où placez-vous la limite ?"}
    ]},
    3:{icon:'🟠',title:'IA et droits',central:'Quelles limites juridiques et éthiques ?',color:'#d87b18',questions:[
      "Peut-on utiliser le visage ou la voix d’une personne avec une IA sans son accord ?",
      "Qui est l’auteur d’une image ou d’un texte créé avec une IA ?",
      "Quelles lignes rouges devraient être les mêmes dans tous les établissements ?",
      "Comment protéger les personnes sans empêcher tous les usages créatifs de l’IA ?"
    ],dilemmas:[
      {text:"Pour faire rire ses amis, un élève crée une chanson qui imite parfaitement la voix d’un camarade sans lui demander son accord.",question:"Acceptable ou non ? Qu’est-ce qui pose problème ?"},
      {text:"Vous créez une très belle affiche avec une IA à partir du style d’un artiste vivant, puis vous la publiez comme votre création.",question:"Que faudrait-il signaler ? Qui a contribué à l’œuvre ?"},
      {text:"Une IA peut générer un contenu choquant, mais l’élève affirme qu’il ne faisait que ‘tester l’outil’.",question:"Quelles limites devraient être non négociables ?"}
    ]},
    4:{icon:'🟣',title:'IA et avenir des compétences',central:'Que doit encore apprendre un humain ?',color:'#7650b3',questions:[
      "Si les réponses sont disponibles immédiatement, qu’est-ce que ‘bien apprendre’ veut encore dire ?",
      "Quelles compétences humaines deviennent plus importantes quand l’IA sait produire très vite ?",
      "Comment évaluer la compréhension plutôt que la simple production d’une réponse ?",
      "Quelles décisions ou questions doivent rester profondément humaines ?"
    ],dilemmas:[
      {text:"Une IA peut résumer parfaitement un cours de 20 pages en quelques secondes.",question:"Faut-il encore apprendre à résumer soi-même ? Pourquoi ?"},
      {text:"Un élève produit un excellent texte avec l’IA, mais il est incapable d’expliquer à l’oral les idées utilisées.",question:"Que devrait mesurer l’évaluation ?"},
      {text:"Une IA sait proposer des solutions logiques à un problème complexe, mais elle ne vit pas les conséquences de ses choix.",question:"Quelles décisions doivent rester humaines ?"}
    ]}
  };

  const emptyRotation=()=>({contributors:[],lab:{force:'',risk:'',human:''},dilemmaIndex:null,position:'',dilemmaWhy:'',dilemmaRule:'',bestQuestion:'',reflection:''});
  const emptyState=()=>({
    tableName:'',pole:1,step:0,labImport:null,
    rotations:{1:emptyRotation(),2:emptyRotation(),3:emptyRotation(),4:emptyRotation()},
    snapshots:{1:null,2:null,3:null,4:null},
    ideas:[],candidates:[],
    synthesis:{retainedIds:[],openQuestion:'',protect:'',allow:'',refuse:'',note:''},
    assembly:{imports:[],criteria:{},finalArticles:[],preamble:'',openQuestion:'',learning:''}
  });

  function normalize(raw){
    const base=emptyState(), s={...base,...(raw||{})};
    s.rotations={...base.rotations,...(s.rotations||{})};
    [1,2,3,4].forEach(r=>s.rotations[r]={...emptyRotation(),...(s.rotations[r]||{}),lab:{...emptyRotation().lab,...(s.rotations[r]?.lab||{})}});
    s.snapshots={...base.snapshots,...(s.snapshots||{})};
    s.ideas=Array.isArray(s.ideas)?s.ideas:[]; s.candidates=Array.isArray(s.candidates)?s.candidates:[];
    s.synthesis={...base.synthesis,...(s.synthesis||{})}; s.synthesis.retainedIds=Array.isArray(s.synthesis.retainedIds)?s.synthesis.retainedIds:[];
    s.assembly={...base.assembly,...(s.assembly||{})}; s.assembly.imports=Array.isArray(s.assembly.imports)?s.assembly.imports:[]; s.assembly.criteria=s.assembly.criteria||{}; s.assembly.finalArticles=Array.isArray(s.assembly.finalArticles)?s.assembly.finalArticles:[];
    return s;
  }
  function load(){try{return normalize(JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}'))}catch{return emptyState()}}
  let state=load();
  let activeStep=Number(state.step||0), timerSeconds=600,timerId=null,timerRunning=false;

  function save(show=true){state.step=activeStep;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));if(show){const el=$('#saveStatus');if(el){el.textContent='✓ Sauvegardé sur cet appareil';setTimeout(()=>el.textContent='💾 Sauvegarde locale active',1200)}}}
  function toast(icon,title,text,long=false){const t=$('#rotationToast');if(!t)return;t.querySelector('.toast-icon').textContent=icon;t.querySelector('strong').textContent=title;t.querySelector('span').textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),long?6000:3600)}

  const clone=v=>JSON.parse(JSON.stringify(v));
  function buildRotationSnapshot(r){
    const rot=state.rotations[r],p=pole(),d=p.dilemmas[rot.dilemmaIndex??0]||null;
    return {
      rotation:r, capturedAt:new Date().toISOString(), pole:Number(state.pole), poleTitle:p.title, central:p.central,
      contributors:clone(rot.contributors||[]), lab:clone(rot.lab||{}),
      ideas:clone(state.ideas||[]), candidates:clone((state.candidates||[]).filter(c=>Number(c.rotation)<=r)),
      dilemma:d?{text:d.text,question:d.question,position:rot.position||'',why:rot.dilemmaWhy||'',rule:rot.dilemmaRule||''}:null,
      bestQuestion:rot.bestQuestion||'', reflection:rot.reflection||''
    };
  }
  function captureRotation(r){if(r<1||r>4)return;state.snapshots[r]=buildRotationSnapshot(r);save(false)}
  function getRotationSnapshot(r){return state.snapshots?.[r]||buildRotationSnapshot(r)}

  function pole(){return poleData[Number(state.pole)]}
  function go(step){const target=Number(step);if(activeStep>=1&&activeStep<=4&&target>activeStep)captureRotation(activeStep);activeStep=target;$$('.panel').forEach(p=>p.classList.toggle('visible',Number(p.dataset.panel)===activeStep));$$('.step').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===activeStep));if(activeStep>=1&&activeStep<=4)renderRotation(activeStep);if(activeStep===5)renderSynthesis();if(activeStep===6)renderAssembly();resetTimer();save(false);window.scrollTo({top:0,behavior:'smooth'})}
  $$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));$$('.step').forEach(b=>b.addEventListener('click',()=>go(b.dataset.step)));

  $('#tableName').value=state.tableName||'';$('#tableName').addEventListener('input',e=>{state.tableName=e.target.value;save()});
  $('#poleSelect').value=String(state.pole||1);$('#poleSelect').addEventListener('change',e=>{state.pole=Number(e.target.value);save();renderPoleMini();if(activeStep>=1&&activeStep<=4)renderRotation(activeStep);if(activeStep===5)renderSynthesis()});
  function renderPoleMini(){const p=pole();$('#poleMini').innerHTML=`<b>${p.icon} ${esc(p.title)}</b><span>${esc(p.central)}</span>`;$('#poleMini').style.borderColor=p.color} renderPoleMini();

  function extractLab(raw){
    if(!raw||typeof raw!=='object')return null;const f=raw.fields||{};
    const forces=[f.force1,f.force2,f.force3].filter(Boolean), risks=[f.risk1,f.risk2,f.risk3].filter(Boolean);
    return {groupName:raw.groupName||'',team:Array.isArray(raw.team)?raw.team.filter(x=>x?.name||x?.school):[],forces,risks,human:f.human_skill||'',ethical:f.ethical_question||'',rule:f.final_rule||''};
  }
  function applyLab(raw){const lab=extractLab(raw);if(!lab){toast('⚠️','Fichier non reconnu','Cette sauvegarde ne ressemble pas à celle du LAB IA.');return}state.labImport=lab;if(!state.rotations[1].lab.force)state.rotations[1].lab.force=lab.forces[0]||'';if(!state.rotations[1].lab.risk)state.rotations[1].lab.risk=lab.risks[0]||'';if(!state.rotations[1].lab.human)state.rotations[1].lab.human=lab.human||'';if(!state.rotations[1].contributors.length&&lab.team.length)state.rotations[1].contributors=lab.team.map(p=>({name:p.name||'',school:p.school||''})).filter(p=>p.name||p.school);save();renderLabBridge();toast('🧪','Bilan récupéré','Vos constats du LAB IA peuvent maintenant nourrir la charte.')}
  $('#importLabLocal').addEventListener('click',()=>{try{const raw=JSON.parse(localStorage.getItem(LAB_KEY)||'null');if(!raw){toast('ℹ️','Aucun LAB IA trouvé','Vous pouvez importer une sauvegarde JSON du LAB IA.');return}applyLab(raw)}catch{toast('⚠️','Lecture impossible','Le bilan local du LAB IA n’a pas pu être lu.')}});
  $('#importLabFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{applyLab(JSON.parse(r.result))}catch{toast('⚠️','Fichier invalide','Choisissez une sauvegarde JSON du LAB IA.')}};r.readAsText(f)});
  function renderLabBridge(){const el=$('#labBridgeSummary'),l=state.labImport;if(!l){el.innerHTML='<span class="empty-note">Aucun bilan du LAB IA récupéré pour le moment.</span>';return}el.innerHTML=`<div class="lab-summary-card"><b>💪 Forces observées</b><span>${esc(l.forces.join(' • ')||'—')}</span></div><div class="lab-summary-card"><b>⚠️ Risques observés</b><span>${esc(l.risks.join(' • ')||'—')}</span></div><div class="lab-summary-card"><b>🧠 Compétence humaine</b><span>${esc(l.human||'—')}</span></div><div class="lab-summary-card wide"><b>📌 Votre règle d’usage</b><span>${esc(l.rule||'—')}</span></div>`} renderLabBridge();

  function contributorHtml(r){const list=state.rotations[r].contributors||[];return `<div class="contributors charter-contributors"><div class="contributors-head"><div><h3>👥 Qui participe à cette rotation ?</h3><p class="contributors-sub">Ajoutez votre prénom et votre établissement. Les groupes suivants verront qui a contribué avant eux.</p></div></div><div class="inline-person-form"><input data-person-name placeholder="Prénom"><input data-person-school placeholder="Établissement / ville"><button class="btn secondary small" data-add-person>+ Ajouter</button></div><div class="people-list">${list.length?list.map((p,i)=>`<span class="person-chip"><strong>${esc(p.name)}</strong><small>${esc(p.school)}</small><button data-remove-person="${i}" title="Supprimer">×</button></span>`).join(''):'<span class="empty-note">Aucun prénom ajouté pour cette rotation.</span>'}</div></div>`}

  function labTraceHtml(r){const l=state.rotations[r].lab;return `<section class="rotation-lab-trace"><div><span class="kicker">Ce que votre groupe apporte du LAB IA</span><h3>🧪 Partez d’une expérience réelle</h3><p>Notez un constat très court. Il servira ensuite à proposer une règle.</p></div><div class="lab-trace-grid"><label>💪 Une force observée<input data-lab-field="force" value="${esc(l.force)}" placeholder="Ex. gagner du temps pour explorer plusieurs idées"></label><label>⚠️ Un risque observé<input data-lab-field="risk" value="${esc(l.risk)}" placeholder="Ex. accepter une réponse fausse sans vérifier"></label><label>🧠 Une compétence humaine importante<input data-lab-field="human" value="${esc(l.human)}" placeholder="Ex. vérifier, juger, expliquer, décider"></label></div></section>`}

  function questionsHtml(){return `<section class="charter-question-zone"><span class="kicker">Questions pour lancer le débat</span><div class="charter-question-grid">${pole().questions.map((q,i)=>`<article><span>${i+1}</span><p>${esc(q)}</p></article>`).join('')}</div></section>`}

  function ideaCard(it,r){const contrib=(it.contributions||[]).map(c=>`<li><b>${esc({keep:'Gardé',enrich:'Enrichi',reform:'Reformulé',question:'Questionné'}[c.action]||c.action)}</b> — ${esc(c.text||'accord du groupe')} <small>(rotation ${c.rotation})</small></li>`).join('');const score=(it.support||0)+(it.contributions?.length||0);return `<article class="collective-idea" data-idea-id="${it.id}"><div class="idea-head"><div><span class="idea-origin">Rotation ${it.rotation}</span><h4>${esc(it.text)}</h4></div><span class="idea-score">${score} interaction${score>1?'s':''}</span></div>${contrib?`<details><summary>Voir les enrichissements</summary><ul>${contrib}</ul></details>`:''}<div class="idea-response"><select data-idea-action><option value="keep">✅ Nous gardons</option><option value="enrich">➕ Nous enrichissons</option><option value="reform">🔄 Nous reformulons</option><option value="question">⚠️ Nous questionnons</option></select><input data-idea-response placeholder="Expliquez votre ajout, votre nuance ou votre question…"><button class="btn ghost small" data-add-response>Ajouter notre contribution</button></div><button class="btn article-btn small" data-article-from-idea>⚖️ Transformer en article</button></article>`}

  function ideasHtml(r){const ideas=[...state.ideas];return `<section class="collective-wall"><div class="section-heading"><div><span class="kicker">Mur d’idées de cette table</span><h3>Ce que les groupes ont déjà construit</h3><p>${r===1?'Vous commencez le mur. Proposez des idées simples et discutables.':'Lisez d’abord les idées existantes. Vous pouvez les garder, les enrichir, les reformuler ou les questionner.'}</p></div><div class="idea-count">${ideas.length} idée${ideas.length!==1?'s':''}</div></div><div class="collective-idea-list">${ideas.length?ideas.map(i=>ideaCard(i,r)).join(''):'<div class="empty-wall">💭 Le mur est encore vide. Ajoutez la première idée.</div>'}</div><div class="new-idea-form"><textarea data-new-idea placeholder="Écrivez une idée, une règle possible, un problème ou une proposition…"></textarea><button class="btn secondary" data-add-idea>+ Ajouter au mur</button></div></section>`}

  function dilemmaHtml(r){const rot=state.rotations[r],data=pole();if(rot.dilemmaIndex===null||rot.dilemmaIndex===undefined)rot.dilemmaIndex=Math.floor(Math.random()*data.dilemmas.length);const d=data.dilemmas[rot.dilemmaIndex];return `<section class="dilemma-card"><div class="dilemma-top"><div><span class="kicker">Carte dilemme</span><h3>🎴 Que décidez-vous ?</h3></div><button class="btn ghost small" data-new-dilemma>🎲 Autre cas</button></div><blockquote>${esc(d.text)}</blockquote><p class="dilemma-question">${esc(d.question)}</p><div class="position-buttons" data-position-group><button data-pos="acceptable" class="${rot.position==='acceptable'?'active ok':''}">🟢 Acceptable</button><button data-pos="conditions" class="${rot.position==='conditions'?'active warn':''}">🟠 Sous conditions</button><button data-pos="unacceptable" class="${rot.position==='unacceptable'?'active stop':''}">🔴 Inacceptable</button></div><label>Pourquoi ?<textarea data-rot-field="dilemmaWhy" placeholder="Expliquez votre choix en quelques phrases.">${esc(rot.dilemmaWhy)}</textarea></label><label>Quelle règle pourrait découler de ce cas ?<textarea data-rot-field="dilemmaRule" placeholder="Ex. Nous pouvons utiliser l’IA pour… à condition de…">${esc(rot.dilemmaRule)}</textarea></label><button class="btn article-btn" data-article-from-dilemma>⚖️ Proposer cette règle comme article</button></section>`}

  function candidatesHtml(r){const list=state.candidates.filter(c=>c.rotation===r);return `<section class="article-workshop"><div><span class="kicker">Fabrique des règles</span><h3>⚖️ Vos propositions d’articles</h3><p>Un bon article est court, compréhensible et applicable dans plusieurs établissements.</p></div><div class="candidate-list">${list.length?list.map(c=>`<article class="candidate-mini"><span class="candidate-type type-${c.type}">${esc(typeLabel(c.type))}</span><p>${esc(c.text)}</p><button data-delete-candidate="${c.id}" title="Supprimer">×</button></article>`).join(''):'<span class="empty-note">Aucun article proposé pendant cette rotation.</span>'}</div><div class="candidate-form"><select data-candidate-type><option value="right">🟢 Un droit</option><option value="responsibility">🔵 Une responsabilité</option><option value="redline">🔴 Une ligne rouge</option><option value="skill">🟣 Une compétence à préserver</option></select><textarea data-candidate-text placeholder="Ex. Nous devons toujours vérifier une information générée par IA avant de la partager."></textarea><input data-candidate-reason placeholder="Pourquoi cette règle est-elle importante ?"><button class="btn secondary" data-add-candidate>+ Proposer l’article</button></div></section>`}
  function typeLabel(t){return {right:'Droit',responsibility:'Responsabilité',redline:'Ligne rouge',skill:'Compétence à préserver'}[t]||'Article'}

  function rotationMemoryHtml(currentR){
    const done=[1,2,3,4].filter(n=>n<currentR && state.snapshots?.[n]);
    if(!done.length)return '';
    return `<section class="rotation-memory"><div class="rotation-memory-head"><div><span class="kicker">Mémoire du mur</span><h3>🧠 Ce qui a été proposé avant votre arrivée</h3><p>Ouvrez une rotation pour retrouver l'état du mur à ce moment-là.</p></div><span>${done.length} rotation${done.length>1?'s':''} conservée${done.length>1?'s':''}</span></div><div class="rotation-memory-list">${done.map(n=>{const snap=state.snapshots[n],ideas=snap.ideas||[];return `<details class="memory-rotation"><summary><b>Rotation ${n}</b><span>${ideas.length} idée${ideas.length!==1?'s':''} • ${(snap.contributors||[]).length} participant${(snap.contributors||[]).length!==1?'s':''}</span></summary><div class="memory-body"><div class="memory-people"><strong>Participants</strong><p>${(snap.contributors||[]).length?snap.contributors.map(p=>`${esc(p.name)} (${esc(p.school)})`).join(' • '):'—'}</p></div><div class="memory-wall"><strong>État du mur à la fin de la rotation ${n}</strong>${ideas.length?`<ol>${ideas.map(i=>`<li>${esc(i.text)}</li>`).join('')}</ol>`:'<p>—</p>'}</div>${snap.bestQuestion?`<div><strong>❓ Question laissée ouverte</strong><p>${esc(snap.bestQuestion)}</p></div>`:''}${snap.reflection?`<div><strong>🧠 Ce que le groupe retenait</strong><p>${esc(snap.reflection)}</p></div>`:''}</div></details>`}).join('')}</div></section>`;
  }

  function renderRotation(r){const mount=$(`.rotation-mount[data-rotation="${r}"]`),rot=state.rotations[r],p=pole();if(!mount)return;mount.innerHTML=`<div class="section-heading"><div><span class="kicker">Rotation ${r} • 10 minutes</span><h2>${p.icon} ${esc(p.title)}</h2><p class="lead"><strong>Question centrale :</strong> ${esc(p.central)}</p></div><div class="phase-badge">${r}</div></div>${r>1?`<div class="previous-note"><strong>💬 Vous arrivez après ${r-1} groupe${r>2?'s':''}.</strong><div>Commencez par lire le mur d’idées avant d’ajouter votre point de vue.</div></div>`:''}${rotationMemoryHtml(r)}${contributorHtml(r)}${labTraceHtml(r)}${questionsHtml()}${ideasHtml(r)}${dilemmaHtml(r)}${candidatesHtml(r)}<label class="reflection-block"><strong>❓ Notre meilleure question</strong><span>Votre but n’est pas seulement de trouver une réponse. Formulez la question qui vous semble la plus importante à garder ouverte.</span><textarea data-rot-field="bestQuestion" placeholder="La question que nous voulons transmettre…">${esc(rot.bestQuestion)}</textarea></label><label class="reflection-block"><strong>🧠 Ce que notre groupe retient de cette rotation</strong><textarea data-rot-field="reflection" placeholder="Notre idée principale, notre désaccord ou notre découverte…">${esc(rot.reflection)}</textarea></label><div class="nav-actions"><button class="btn ghost" data-go-local="${r-1}">← ${r===1?'Mission':'Rotation '+(r-1)}</button><button class="btn primary" data-go-local="${r===4?5:r+1}">${r===4?'Faire la synthèse du pôle':'Rotation '+(r+1)+' →'}</button></div>`;
    bindRotation(mount,r);
  }

  function bindRotation(mount,r){
    mount.addEventListener('click',e=>{
      const btn=e.target.closest('button');if(!btn)return;
      if(btn.dataset.goLocal!==undefined){go(Number(btn.dataset.goLocal));return}
      if(btn.hasAttribute('data-add-person')){const name=$('[data-person-name]',mount).value.trim(),school=$('[data-person-school]',mount).value.trim();if(!name||!school){toast('👥','Prénom et établissement','Renseignez les deux champs avant d’ajouter.');return}state.rotations[r].contributors.push({name,school});save();renderRotation(r);return}
      if(btn.dataset.removePerson!==undefined){state.rotations[r].contributors.splice(Number(btn.dataset.removePerson),1);save();renderRotation(r);return}
      if(btn.hasAttribute('data-add-idea')){const text=$('[data-new-idea]',mount).value.trim();if(!text)return;state.ideas.push({id:uid(),text,rotation:r,support:0,contributions:[]});save();renderRotation(r);return}
      if(btn.hasAttribute('data-add-response')){const card=btn.closest('.collective-idea'),id=card.dataset.ideaId,it=state.ideas.find(x=>x.id===id);if(!it)return;const action=$('[data-idea-action]',card).value,text=$('[data-idea-response]',card).value.trim();if(action!=='keep'&&!text){toast('✍️','Expliquez votre choix','Ajoutez une courte phrase pour enrichir, reformuler ou questionner.');return}if(action==='keep')it.support=(it.support||0)+1;it.contributions=it.contributions||[];it.contributions.push({rotation:r,action,text});save();renderRotation(r);return}
      if(btn.hasAttribute('data-article-from-idea')){const card=btn.closest('.collective-idea'),it=state.ideas.find(x=>x.id===card.dataset.ideaId);if(!it)return;$('[data-candidate-text]',mount).value=it.text;$('[data-candidate-text]',mount).focus();$('[data-candidate-text]',mount).scrollIntoView({behavior:'smooth',block:'center'});return}
      if(btn.hasAttribute('data-new-dilemma')){const d=pole().dilemmas;let ix;do{ix=Math.floor(Math.random()*d.length)}while(ix===state.rotations[r].dilemmaIndex&&d.length>1);state.rotations[r].dilemmaIndex=ix;state.rotations[r].position='';state.rotations[r].dilemmaWhy='';state.rotations[r].dilemmaRule='';save();renderRotation(r);return}
      if(btn.dataset.pos){state.rotations[r].position=btn.dataset.pos;save();renderRotation(r);return}
      if(btn.hasAttribute('data-article-from-dilemma')){const text=state.rotations[r].dilemmaRule.trim();if(!text){toast('⚖️','Écrivez d’abord la règle','Formulez une règle à partir du dilemme avant de la proposer.');return}$('[data-candidate-text]',mount).value=text;$('[data-candidate-text]',mount).scrollIntoView({behavior:'smooth',block:'center'});return}
      if(btn.hasAttribute('data-add-candidate')){const type=$('[data-candidate-type]',mount).value,text=$('[data-candidate-text]',mount).value.trim(),reason=$('[data-candidate-reason]',mount).value.trim();if(!text)return;state.candidates.push({id:uid(),pole:Number(state.pole),rotation:r,type,text,reason,retained:false});save();renderRotation(r);return}
      if(btn.dataset.deleteCandidate){state.candidates=state.candidates.filter(c=>c.id!==btn.dataset.deleteCandidate);state.synthesis.retainedIds=state.synthesis.retainedIds.filter(id=>id!==btn.dataset.deleteCandidate);save();renderRotation(r);return}
    });
    $$('[data-lab-field]',mount).forEach(el=>el.addEventListener('input',()=>{state.rotations[r].lab[el.dataset.labField]=el.value;save()}));
    $$('[data-rot-field]',mount).forEach(el=>el.addEventListener('input',()=>{state.rotations[r][el.dataset.rotField]=el.value;save()}));
  }

  function poleSummary(){const p=pole();[1,2,3,4].forEach(r=>{if(!state.snapshots[r])state.snapshots[r]=buildRotationSnapshot(r)});const retained=state.candidates.filter(c=>state.synthesis.retainedIds.includes(c.id));const chosen=retained.length?retained:state.candidates.slice(0,3);return {kind:'intercvl-charte-pole-v1',pole:Number(state.pole),poleTitle:p.title,central:p.central,tableName:state.tableName||'',candidates:chosen.map(c=>({...c})),openQuestion:state.synthesis.openQuestion||'',protect:state.synthesis.protect||'',allow:state.synthesis.allow||'',refuse:state.synthesis.refuse||'',note:state.synthesis.note||'',contributors:allContributors(),trace:{labImport:clone(state.labImport),snapshots:[1,2,3,4].map(r=>clone(getRotationSnapshot(r))),ideasFinal:clone(state.ideas),candidatesAll:clone(state.candidates),synthesis:clone(state.synthesis)}}}
  function allContributors(){const m=new Map();Object.values(state.rotations).flatMap(r=>r.contributors||[]).forEach(p=>m.set(`${(p.name||'').toLowerCase()}|${(p.school||'').toLowerCase()}`,p));return [...m.values()]}

  function renderSynthesis(){const box=$('#poleSynthesis'),p=pole();const sorted=[...state.ideas].sort((a,b)=>((b.support||0)+(b.contributions?.length||0))-((a.support||0)+(a.contributions?.length||0)));const questions=[...new Set(Object.values(state.rotations).map(r=>r.bestQuestion?.trim()).filter(Boolean))];box.innerHTML=`<div class="synthesis-pole-banner" style="border-color:${p.color}"><div><span>${p.icon}</span><div><b>${esc(p.title)}</b><p>${esc(p.central)}</p></div></div><span>${state.ideas.length} idées • ${state.candidates.length} articles candidats</span></div><section class="synthesis-ideas"><h3>1. Les idées qui ont le plus circulé</h3><div class="top-ideas">${sorted.length?sorted.slice(0,6).map((i,n)=>`<article><span>${n+1}</span><p>${esc(i.text)}</p><small>${(i.support||0)+(i.contributions?.length||0)} interaction(s)</small></article>`).join(''):'<span class="empty-note">Aucune idée enregistrée.</span>'}</div></section><section class="synthesis-candidates"><div><h3>2. Choisissez 2 ou 3 articles à envoyer à l’Assemblée finale</h3><p>Ne gardez pas tout. Retenez ce qui vous paraît le plus clair et le plus utile pour toute la zone.</p></div><div class="retained-list">${state.candidates.length?state.candidates.map(c=>`<label class="retain-card ${state.synthesis.retainedIds.includes(c.id)?'selected':''}"><input type="checkbox" data-retain="${c.id}" ${state.synthesis.retainedIds.includes(c.id)?'checked':''}><span class="candidate-type type-${c.type}">${esc(typeLabel(c.type))}</span><p>${esc(c.text)}</p><small>${esc(c.reason||'')}</small></label>`).join(''):'<span class="empty-note">Aucun article candidat. Revenez aux rotations pour en proposer.</span>'}</div></section><section class="synthesis-core"><h3>3. Résumez la position de votre pôle</h3><div class="summary-grid"><label>🛡️ Ce que nous voulons protéger<textarea data-synth="protect">${esc(state.synthesis.protect)}</textarea></label><label>✅ Ce que nous voulons permettre<textarea data-synth="allow">${esc(state.synthesis.allow)}</textarea></label><label>⛔ Ce que nous refusons<textarea data-synth="refuse">${esc(state.synthesis.refuse)}</textarea></label><label>💬 Notre message en une phrase<textarea data-synth="note">${esc(state.synthesis.note)}</textarea></label></div></section><section class="open-question-choice"><h3>4. Quelle question mérite de rester ouverte ?</h3>${questions.length?questions.map(q=>`<label><input type="radio" name="openQ" data-open-question value="${esc(q)}" ${state.synthesis.openQuestion===q?'checked':''}> ${esc(q)}</label>`).join(''):'<span class="empty-note">Aucune question n’a encore été formulée pendant les rotations.</span>'}<label>Ou écrivez-en une autre<textarea data-synth="openQuestion">${esc(state.synthesis.openQuestion)}</textarea></label></section><section class="pole-export-box"><div><h3>📦 La synthèse de votre pôle est prête</h3><p>Téléchargez ce petit fichier. Il sera importé pendant l’Assemblée finale avec les synthèses des trois autres pôles.</p></div><div><button class="btn primary" id="exportPole">Télécharger la synthèse du pôle</button><button class="btn ghost" id="printPole">📄 Imprimer / PDF du pôle</button></div></section>`;
    $$('[data-retain]',box).forEach(el=>el.addEventListener('change',()=>{const id=el.dataset.retain;const arr=state.synthesis.retainedIds;if(el.checked&&!arr.includes(id)){if(arr.length>=3){el.checked=false;toast('🎯','Maximum 3 articles','Choisissez seulement 2 ou 3 propositions fortes.');return}arr.push(id)}else if(!el.checked){state.synthesis.retainedIds=arr.filter(x=>x!==id)}save();renderSynthesis()}));
    $$('[data-synth]',box).forEach(el=>el.addEventListener('input',()=>{state.synthesis[el.dataset.synth]=el.value;save()}));
    $$('[data-open-question]',box).forEach(el=>el.addEventListener('change',()=>{state.synthesis.openQuestion=el.value;save();renderSynthesis()}));
    $('#exportPole').addEventListener('click',downloadPoleSummary);$('#printPole').addEventListener('click',printPoleSummary);
  }

  function downloadPoleSummary(){const data=poleSummary(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`CharteIA_Pole${state.pole}_${(state.tableName||'table').replace(/[^a-z0-9_-]+/gi,'_')}.json`;a.click();URL.revokeObjectURL(a.href);toast('📦','Synthèse téléchargée','Gardez ce fichier pour l’Assemblée finale.')}
  function poleSummaryHtml(){const s=poleSummary(),p=pole();return `<div class="preview-doc charter-preview"><div class="preview-logos"><img src="assets/logo-zese.png"><img src="assets/logo-aefe.png"></div><h1>Charte IA ZESE — Synthèse du pôle ${s.pole}</h1><h2>${p.icon} ${esc(s.poleTitle)}</h2><p><strong>${esc(s.central)}</strong></p><section><h2>Articles proposés</h2>${s.candidates.length?s.candidates.map((c,i)=>`<h3>${i+1}. ${esc(typeLabel(c.type))}</h3><div class="answer">${esc(c.text)}</div>`).join(''):'<div class="answer">—</div>'}</section><section><h2>Notre position</h2><h3>À protéger</h3><div class="answer">${esc(s.protect||'—')}</div><h3>À permettre</h3><div class="answer">${esc(s.allow||'—')}</div><h3>À refuser</h3><div class="answer">${esc(s.refuse||'—')}</div><h3>Question ouverte</h3><div class="answer">${esc(s.openQuestion||'—')}</div></section><section><h2>Personnes ayant contribué</h2><div class="answer">${s.contributors.length?s.contributors.map(p=>`${esc(p.name)} (${esc(p.school)})`).join(' • '):'—'}</div></section></div>`}
  function printElement(html){const old=$('#printSummary');if(old)old.remove();const el=document.createElement('div');el.id='printSummary';el.className='print-summary';el.innerHTML=html;document.body.appendChild(el);document.body.classList.add('printing-summary');const clean=()=>{document.body.classList.remove('printing-summary');el.remove();window.removeEventListener('afterprint',clean)};window.addEventListener('afterprint',clean);setTimeout(()=>window.print(),80)}
  function printPoleSummary(){printElement(poleSummaryHtml())}

  function importPole(summary){if(!summary||summary.kind!=='intercvl-charte-pole-v1'||![1,2,3,4].includes(Number(summary.pole))){toast('⚠️','Synthèse non reconnue','Choisissez un fichier de synthèse créé par cet atelier.');return false}state.assembly.imports=state.assembly.imports.filter(x=>Number(x.pole)!==Number(summary.pole));state.assembly.imports.push(summary);state.assembly.imports.sort((a,b)=>a.pole-b.pole);save();renderAssembly();return true}
  $('#addCurrentPole').addEventListener('click',()=>{importPole(poleSummary());toast('✅','Pôle ajouté','La synthèse de cette table est maintenant dans l’Assemblée finale.')});
  $('#poleImportInput').addEventListener('change',e=>{const files=[...e.target.files];files.forEach(file=>{const r=new FileReader();r.onload=()=>{try{importPole(JSON.parse(r.result))}catch{toast('⚠️','Fichier invalide',`Impossible de lire ${file.name}.`)}};r.readAsText(file)});e.target.value=''});

  function allAssemblyCandidates(){return state.assembly.imports.flatMap(s=>(s.candidates||[]).map(c=>({...c,sourcePole:s.pole,sourceTitle:s.poleTitle,key:`p${s.pole}_${c.id}`})))}
  function finalHasKey(key){return state.assembly.finalArticles.some(a=>a.sourceKey===key)}
  function renderAssembly(){
    $('#charterPreamble').value=state.assembly.preamble||'';$('#finalOpenQuestion').value=state.assembly.openQuestion||'';$('#finalLearning').value=state.assembly.learning||'';
    $('#importedPoles').innerHTML=[1,2,3,4].map(n=>{const s=state.assembly.imports.find(x=>Number(x.pole)===n),p=poleData[n];return `<article class="imported-pole ${s?'loaded':''}"><span>${p.icon}</span><div><b>Pôle ${n} — ${esc(p.title)}</b><small>${s?`${(s.candidates||[]).length} article(s) importé(s)`:'À importer'}</small></div>${s?`<button data-remove-import="${n}" title="Retirer">×</button>`:''}</article>`}).join('');
    $$('[data-remove-import]').forEach(b=>b.addEventListener('click',()=>{state.assembly.imports=state.assembly.imports.filter(x=>Number(x.pole)!==Number(b.dataset.removeImport));save();renderAssembly()}));
    const candidates=allAssemblyCandidates();$('#candidateBoard').innerHTML=candidates.length?candidates.map(c=>{const cr=state.assembly.criteria[c.key]||{fair:false,applicable:false,zese:false};const score=[cr.fair,cr.applicable,cr.zese].filter(Boolean).length;return `<article class="assembly-candidate"><div class="candidate-source">${poleData[c.sourcePole].icon} Pôle ${c.sourcePole}</div><span class="candidate-type type-${c.type}">${esc(typeLabel(c.type))}</span><p>${esc(c.text)}</p><div class="criteria-row"><button data-criterion="fair" data-key="${c.key}" class="${cr.fair?'active':''}">⚖️ Juste</button><button data-criterion="applicable" data-key="${c.key}" class="${cr.applicable?'active':''}">🎯 Applicable</button><button data-criterion="zese" data-key="${c.key}" class="${cr.zese?'active':''}">🌍 ZESE</button><strong>${score}/3</strong></div><button class="btn ${finalHasKey(c.key)?'ghost':'secondary'} small" data-add-final="${c.key}" ${finalHasKey(c.key)?'disabled':''}>${finalHasKey(c.key)?'✓ Dans la charte':'+ Ajouter à la charte'}</button></article>`}).join(''):'<div class="empty-wall">📂 Importez d’abord les synthèses des pôles.</div>';
    $$('[data-criterion]').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.key,crit=b.dataset.criterion;state.assembly.criteria[k]||={fair:false,applicable:false,zese:false};state.assembly.criteria[k][crit]=!state.assembly.criteria[k][crit];save();renderAssembly()}));
    $$('[data-add-final]').forEach(b=>b.addEventListener('click',()=>{const c=candidates.find(x=>x.key===b.dataset.addFinal);if(!c)return;if(state.assembly.finalArticles.length>=12){toast('📜','12 articles maximum','Fusionnez ou retirez une proposition avant d’en ajouter une autre.');return}state.assembly.finalArticles.push({id:uid(),sourceKey:c.key,title:`Article ${state.assembly.finalArticles.length+1}`,type:c.type,text:c.text});save();renderAssembly()}));
    renderFinalArticles();
  }

  function renderFinalArticles(){const box=$('#finalArticles'),list=state.assembly.finalArticles;$('#articleCounter').textContent=`${list.length} / 12 articles`;$('#articleCounter').className=`article-counter ${list.length>=10&&list.length<=12?'good':list.length>12?'bad':''}`;box.innerHTML=list.length?list.map((a,i)=>`<article class="final-article" data-final-id="${a.id}"><div class="article-order"><button data-move="up" ${i===0?'disabled':''}>↑</button><strong>${i+1}</strong><button data-move="down" ${i===list.length-1?'disabled':''}>↓</button></div><div class="article-edit"><div class="article-edit-top"><input data-final-title value="${esc(a.title)}" placeholder="Titre de l'article"><select data-final-type><option value="right" ${a.type==='right'?'selected':''}>🟢 Droit</option><option value="responsibility" ${a.type==='responsibility'?'selected':''}>🔵 Responsabilité</option><option value="redline" ${a.type==='redline'?'selected':''}>🔴 Ligne rouge</option><option value="skill" ${a.type==='skill'?'selected':''}>🟣 Compétence à préserver</option></select><button data-delete-final title="Supprimer">×</button></div><textarea data-final-text>${esc(a.text)}</textarea></div></article>`).join(''):'<div class="empty-wall">Ajoutez les meilleures propositions depuis les articles candidats, ou créez un article vide.</div>';
    $$('.final-article',box).forEach(card=>{const id=card.dataset.finalId,a=state.assembly.finalArticles.find(x=>x.id===id);$('[data-final-title]',card).addEventListener('input',e=>{a.title=e.target.value;save()});$('[data-final-type]',card).addEventListener('change',e=>{a.type=e.target.value;save()});$('[data-final-text]',card).addEventListener('input',e=>{a.text=e.target.value;save()});$('[data-delete-final]',card).addEventListener('click',()=>{state.assembly.finalArticles=state.assembly.finalArticles.filter(x=>x.id!==id);save();renderAssembly()});$$('[data-move]',card).forEach(b=>b.addEventListener('click',()=>{const ix=state.assembly.finalArticles.findIndex(x=>x.id===id),dir=b.dataset.move==='up'?-1:1,j=ix+dir;if(j<0||j>=state.assembly.finalArticles.length)return;[state.assembly.finalArticles[ix],state.assembly.finalArticles[j]]=[state.assembly.finalArticles[j],state.assembly.finalArticles[ix]];save();renderAssembly()}))});
  }
  $('#addBlankArticle').addEventListener('click',()=>{if(state.assembly.finalArticles.length>=12){toast('📜','12 articles maximum','La charte doit rester courte.');return}state.assembly.finalArticles.push({id:uid(),sourceKey:'',title:`Article ${state.assembly.finalArticles.length+1}`,type:'responsibility',text:''});save();renderAssembly()});
  $('#charterPreamble').addEventListener('input',e=>{state.assembly.preamble=e.target.value;save()});$('#finalOpenQuestion').addEventListener('input',e=>{state.assembly.openQuestion=e.target.value;save()});$('#finalLearning').addEventListener('input',e=>{state.assembly.learning=e.target.value;save()});

  function assemblyContributors(){const m=new Map();state.assembly.imports.flatMap(s=>s.contributors||[]).forEach(p=>m.set(`${(p.name||'').toLowerCase()}|${(p.school||'').toLowerCase()}`,p));return [...m.values()]}
  function actionLabel(a){return {keep:'Gardé',enrich:'Enrichi',reform:'Reformulé',question:'Questionné'}[a]||a||'—'}
  function positionLabel(p){return {acceptable:'🟢 Acceptable',conditions:'🟠 Acceptable sous conditions',unacceptable:'🔴 Inacceptable'}[p]||'—'}
  function poleTraceHtml(summary){
    const pd=poleData[Number(summary.pole)]||{icon:'',title:summary.poleTitle||'',central:summary.central||''};
    const trace=summary.trace||{}, snaps=Array.isArray(trace.snapshots)?trace.snapshots:[];
    const lab=trace.labImport;
    return `<section class="report-pole page-break-before"><div class="report-pole-head"><span>${pd.icon}</span><div><small>PÔLE ${summary.pole}</small><h2>${esc(summary.poleTitle||pd.title)}</h2><p>${esc(summary.central||pd.central)}</p></div></div>
      ${lab?`<div class="report-lab"><h3>🧪 Point de départ : ce que le LAB IA nous avait appris</h3><p><strong>Forces :</strong> ${esc((lab.forces||[]).join(' • ')||'—')}</p><p><strong>Risques :</strong> ${esc((lab.risks||[]).join(' • ')||'—')}</p><p><strong>Compétence humaine :</strong> ${esc(lab.human||'—')}</p><p><strong>Règle d'usage :</strong> ${esc(lab.rule||'—')}</p></div>`:''}
      <div class="report-rotations">${[1,2,3,4].map(r=>rotationTraceHtml(snaps.find(s=>Number(s.rotation)===r),r)).join('')}</div>
      <section><h3>🎯 Synthèse du pôle</h3><p><strong>À protéger :</strong> ${esc(summary.protect||trace.synthesis?.protect||'—')}</p><p><strong>À permettre :</strong> ${esc(summary.allow||trace.synthesis?.allow||'—')}</p><p><strong>À refuser :</strong> ${esc(summary.refuse||trace.synthesis?.refuse||'—')}</p><p><strong>Message du pôle :</strong> ${esc(summary.note||trace.synthesis?.note||'—')}</p><p><strong>Question ouverte :</strong> ${esc(summary.openQuestion||trace.synthesis?.openQuestion||'—')}</p></section>
      <section><h3>⚖️ Articles envoyés à l'Assemblée</h3>${(summary.candidates||[]).length?(summary.candidates||[]).map((c,i)=>`<div class="report-rule"><b>${i+1}. ${esc(typeLabel(c.type))}</b><p>${esc(c.text)}</p>${c.reason?`<small>Pourquoi : ${esc(c.reason)}</small>`:''}</div>`).join(''):'<p>—</p>'}</section>
    </section>`;
  }
  function rotationTraceHtml(snap,r){
    if(!snap)return `<article class="report-rotation"><h3>Rotation ${r}</h3><p>Aucune trace enregistrée.</p></article>`;
    const ideas=snap.ideas||[], contribs=ideas.flatMap(i=>(i.contributions||[]).filter(c=>Number(c.rotation)===r).map(c=>({idea:i.text,...c}))), cand=(snap.candidates||[]).filter(c=>Number(c.rotation)===r);
    return `<article class="report-rotation"><div class="report-rotation-title"><h3>Rotation ${r}</h3><span>${ideas.length} idée${ideas.length!==1?'s':''} sur le mur</span></div>
      <p><strong>Participants :</strong> ${(snap.contributors||[]).length?snap.contributors.map(p=>`${esc(p.name)} (${esc(p.school)})`).join(' • '):'—'}</p>
      ${(snap.lab?.force||snap.lab?.risk||snap.lab?.human)?`<div class="report-mini-grid"><div><b>💪 Force observée</b><p>${esc(snap.lab.force||'—')}</p></div><div><b>⚠️ Risque observé</b><p>${esc(snap.lab.risk||'—')}</p></div><div><b>🧠 Compétence humaine</b><p>${esc(snap.lab.human||'—')}</p></div></div>`:''}
      <h4>Mur des idées à la fin de cette rotation</h4>${ideas.length?`<ol class="report-wall">${ideas.map(i=>`<li><b>${esc(i.text)}</b>${(i.contributions||[]).length?`<ul>${(i.contributions||[]).map(c=>`<li>Rotation ${c.rotation} — ${esc(actionLabel(c.action))}${c.text?` : ${esc(c.text)}`:''}</li>`).join('')}</ul>`:''}</li>`).join('')}</ol>`:'<p>—</p>'}
      ${contribs.length?`<h4>Ce que ce groupe a modifié ou questionné</h4><ul>${contribs.map(c=>`<li><b>${esc(actionLabel(c.action))}</b> — ${esc(c.idea)}${c.text?` → ${esc(c.text)}`:''}</li>`).join('')}</ul>`:''}
      ${snap.dilemma?`<div class="report-dilemma"><h4>🎴 Dilemme travaillé</h4><p>${esc(snap.dilemma.text)}</p><p><strong>Décision :</strong> ${esc(positionLabel(snap.dilemma.position))}</p><p><strong>Pourquoi :</strong> ${esc(snap.dilemma.why||'—')}</p><p><strong>Règle proposée :</strong> ${esc(snap.dilemma.rule||'—')}</p></div>`:''}
      ${cand.length?`<h4>Articles proposés pendant la rotation</h4>${cand.map(c=>`<div class="report-rule"><b>${esc(typeLabel(c.type))}</b><p>${esc(c.text)}</p>${c.reason?`<small>${esc(c.reason)}</small>`:''}</div>`).join('')}`:''}
      <p><strong>❓ Meilleure question :</strong> ${esc(snap.bestQuestion||'—')}</p><p><strong>🧠 Ce que le groupe retient :</strong> ${esc(snap.reflection||'—')}</p>
    </article>`;
  }
  function assemblyTraceHtml(){
    const candidates=allAssemblyCandidates();
    return `<section class="page-break-before"><h2>🏛️ Assemblée finale — Comment la charte a été choisie</h2><p>Les propositions venues des pôles ont été relues selon trois critères : juste, applicable et adaptée à toute la ZESE.</p>${candidates.length?`<div class="report-candidates">${candidates.map(c=>{const cr=state.assembly.criteria[c.key]||{},score=[cr.fair,cr.applicable,cr.zese].filter(Boolean).length;return `<div class="report-candidate"><b>${poleData[c.sourcePole]?.icon||''} Pôle ${c.sourcePole} — ${esc(typeLabel(c.type))}</b><p>${esc(c.text)}</p><small>Évaluation de l'Assemblée : ${score}/3 • ${cr.fair?'⚖️ juste ':''}${cr.applicable?'🎯 applicable ':''}${cr.zese?'🌍 ZESE':''}</small></div>`}).join('')}</div>`:'<p>Aucun article candidat importé.</p>'}</section>`;
  }
  function completeWorkshopHtml(){
    const summaries=[1,2,3,4].map(n=>state.assembly.imports.find(s=>Number(s.pole)===n)).filter(Boolean);
    // Si cette table n'a pas encore été ajoutée, on l'inclut quand même dans le dossier.
    if(!summaries.some(s=>Number(s.pole)===Number(state.pole)))summaries.push(poleSummary());
    summaries.sort((a,b)=>Number(a.pole)-Number(b.pole));
    const people=assemblyContributors(),currentPeople=allContributors(),map=new Map();[...people,...currentPeople].forEach(p=>map.set(`${(p.name||'').toLowerCase()}|${(p.school||'').toLowerCase()}`,p));const everyone=[...map.values()];
    const schools=[...new Set(everyone.map(p=>p.school).filter(Boolean))].sort();
    return `<div class="preview-doc full-workshop-report"><div class="preview-logos"><img src="assets/logo-zese.png"><img src="assets/logo-aefe.png"></div><div class="charter-cover"><span>CARNET COMPLET • INTER-CVL ZESE • NICOSIE</span><h1>Construire la Charte d'usage de l'IA</h1><p>Traces des débats, évolution des idées et charte finale</p></div>
      <section class="report-intro"><h2>À propos de ce document</h2><p>Ce PDF conserve les traces de l'atelier : participants, constats du LAB IA, murs d'idées à chaque rotation, enrichissements, dilemmes, propositions d'articles, synthèses des pôles et décisions de l'Assemblée finale.</p><p><strong>Établissements représentés :</strong> ${esc(schools.join(' • ')||'—')}</p><p><strong>Élèves contributeurs :</strong> ${everyone.length?everyone.map(p=>`${esc(p.name)} (${esc(p.school)})`).join(' • '):'—'}</p></section>
      ${summaries.map(poleTraceHtml).join('')}
      ${assemblyTraceHtml()}
      <div class="page-break-before">${finalCharterHtml(false)}</div>
    </div>`;
  }

  function finalCharterHtml(withWrapper=true){const arts=state.assembly.finalArticles,people=assemblyContributors(),schools=[...new Set(people.map(p=>p.school).filter(Boolean))].sort();const inner=`<div class="preview-logos"><img src="assets/logo-zese.png"><img src="assets/logo-aefe.png"></div><div class="charter-cover"><span>PROPOSITION DES ÉLÈVES • INTER-CVL ZESE • NICOSIE</span><h1>Charte d’usage de l’Intelligence Artificielle</h1><p>Zone Europe du Sud-Est</p></div><section><h2>Notre vision</h2><div class="answer">${esc(state.assembly.preamble||'—')}</div></section><section><h2>Nos articles</h2>${arts.length?arts.map((a,i)=>`<article class="print-charter-article"><span>${i+1}</span><div><small>${esc(typeLabel(a.type))}</small><h3>${esc(a.title||`Article ${i+1}`)}</h3><p>${esc(a.text||'—')}</p></div></article>`).join(''):'<div class="answer">Aucun article rédigé.</div>'}</section><section><h2>Une question reste ouverte</h2><div class="manifesto-quote">${esc(state.assembly.openQuestion||'—')}</div><h2>Ce que ce travail nous a appris</h2><div class="answer">${esc(state.assembly.learning||'—')}</div></section><section><h2>Établissements et élèves contributeurs</h2><p><strong>Établissements représentés :</strong> ${esc(schools.join(' • ')||'—')}</p><div class="answer">${people.length?people.map(p=>`${esc(p.name)} (${esc(p.school)})`).join(' • '):'—'}</div></section>`;return withWrapper?`<div class="preview-doc charter-final-preview">${inner}</div>`:`<section class="charter-final-preview embedded-charter">${inner}</section>`}
  $('#previewBtn').addEventListener('click',()=>{$('#previewContent').innerHTML=completeWorkshopHtml();$('#previewDialog').showModal()});$('#closePreview').addEventListener('click',()=>$('#previewDialog').close());$('#pdfBtn').addEventListener('click',async()=>{[1,2,3,4].forEach(r=>{if(!state.snapshots[r])state.snapshots[r]=buildRotationSnapshot(r)});save(false);const n=state.assembly.finalArticles.length;if(n<10)toast('💡','Votre charte est encore courte',`Vous avez ${n} article(s). L’objectif proposé est 10 à 12, mais vous pouvez quand même générer le PDF complet.`,true);const filename=`Charte_IA_ZESE_${(state.tableName||'assemblee').replace(/[^a-z0-9_-]+/gi,'_')}.pdf`;const result=await window.IntercvlDriveSync?.generateAndSendPdf({atelier:'charte-ia',tableName:state.tableName,jsonBackup:state,html:completeWorkshopHtml(),statusEl:$('#driveSyncStatus'),filename});if(result?.ok)toast('✅','PDF complet enregistré','Le carnet complet et la Charte IA ont été enregistrés directement dans le Drive de l’équipe organisatrice.',true)});
  $('#backupBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CharteIA_ZESE_sauvegarde_complete.json';a.click();URL.revokeObjectURL(a.href)});
  $('#restoreInput').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=normalize(JSON.parse(r.result));localStorage.setItem(STORAGE_KEY,JSON.stringify(state));location.reload()}catch{alert('Cette sauvegarde n’est pas valide.')}};r.readAsText(f)});
  $('#resetAll').addEventListener('click',()=>{if(confirm('Effacer toutes les idées, tous les prénoms et toute la charte sur cet appareil ?')){localStorage.removeItem(STORAGE_KEY);location.reload()}});
  $('#driveSyncBtn')?.addEventListener('click',()=>{window.IntercvlDriveSync?.send('charte-ia',state.tableName,state,$('#driveSyncStatus'))});

  function fmt(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
  function duration(){return activeStep>=1&&activeStep<=4?600:activeStep===6?900:activeStep===5?900:600}
  function updateTimer(){const mins=Math.round(duration()/60);$('#timerDisplay').textContent=fmt(timerSeconds);$('#timerPreset').textContent=`${mins} min`;$('#timerLabel').textContent=activeStep>=1&&activeStep<=4?`Rotation ${activeStep}`:activeStep===5?'Synthèse du pôle':activeStep===6?'Assemblée finale':'Prêt'}
  function startTimer(){if(timerRunning)return;timerRunning=true;timerId=setInterval(()=>{timerSeconds--;updateTimer();if(timerSeconds===120)toast('⏳','Plus que 2 minutes','Commencez à formuler votre meilleure question et vos règles.');if(timerSeconds===30)toast('⚡','30 secondes','Finalisez votre trace avant de changer de table.');if(timerSeconds<=0){pauseTimer();timerSeconds=0;updateTimer();toast('🔄','Temps écoulé',activeStep>=1&&activeStep<=4?'Changez de table : les idées restent ici, les élèves tournent.':'Finalisez votre synthèse.',true)}},1000)}
  function pauseTimer(){if(timerId)clearInterval(timerId);timerRunning=false}function resetTimer(){pauseTimer();timerSeconds=duration();updateTimer()}
  $('#timerStart').addEventListener('click',startTimer);$('#timerPause').addEventListener('click',pauseTimer);$('#timerReset').addEventListener('click',resetTimer);

  renderLabBridge();renderPoleMini();updateTimer();go(activeStep);
})();
